mapper.select:
SELECT 


ORDER BY tc.created_at DESC, tc.id DESC
LIMIT #{offset}, #{pageSize}

mapper.delete:
DELETE FROM dpm_cycle_case_requirement
WHERE cycle_case_id = #{cycleCaseId}
  AND EXISTS (
      SELECT 1 FROM dpm_cycle_case cc
      WHERE cc.id = #{cycleCaseId} AND cc.cycle_id = #{cycleId}
  )
